return ['domain'=>'nibwp','plural-forms'=>'nplurals=6; plural=(n == 0 ? 0 : n == 1 ? 1 : n == 2 ? 2 : n % 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','language'=>'ar','project-id-version'=>'NIBWP 1.2.10','pot-creation-date'=>'2026-09-16T15:42:44+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['NIBWP'=>'NIBWP','https://www.nibwp.com'=>'https://www.nibwp.com','Discover Abilities'=>'اكتشاف القدرات','Find the tools for a subject'=>'العثور على الأدوات المناسبة لموضوع ما','Name a builder, plugin, theme or design tool — or paste the link you are working from.'=>'اذكر أداة بناء أو إضافة أو قالبًا أو أداة تصميم — أو الصق الرابط الذي تعمل انطلاقًا منه.','Not included in this license.'=>'غير مشمول في هذا الترخيص.','Owned, but switched off in NibWP → Skills.'=>'مملوك، لكنه معطّل في NibWP ← المهارات.','Needs %s, which is not installed here. Say so rather than building it another way.'=>'يتطلب %s، وهو غير مثبّت هنا. صرّح بذلك بدلًا من بنائه بطريقة أخرى.',' This site also has a saved workflow for it, "%s" — read it first; it may set the order.'=>' لدى هذا الموقع أيضًا سير عمل محفوظ لهذه المهمة، "%s" — اقرأه أولًا؛ فقد يحدد الترتيب.','%1$s claims this. Run its pipeline in order, starting with %2$s.'=>'تتولى المهارة %1$s هذا الأمر. شغّل مسارها بالترتيب، بدءًا من %2$s.','%1$s would handle this but cannot run: %2$s Tell the user rather than building it another way.'=>'كانت المهارة %1$s ستتولى هذا الأمر لكنها لا تستطيع العمل: %2$s أخبر المستخدم بدلًا من بنائه بطريقة أخرى.','%1$s covers this but is not in the current license. Mention it, then %2$s'=>'تغطي المهارة %1$s هذا الأمر لكنها ليست ضمن الترخيص الحالي. أشِر إليها، ثم %2$s','use the abilities below.'=>'استخدم القدرات أدناه.','carry on with nibwp/execute-php — nothing else here owns the job.'=>'تابع باستخدام nibwp/execute-php — لا شيء آخر هنا يتولى هذه المهمة.','No skill claims this, but this site has a saved workflow for it: "%1$s". Read it and follow it; %2$d matching abilities are available, and nibwp/execute-php covers anything they do not.'=>'لا توجد مهارة تتولى هذا الأمر، لكن لدى هذا الموقع سير عمل محفوظًا له: "%1$s". اقرأه واتبعه؛ تتوفر %2$d من القدرات المطابقة، وتغطي nibwp/execute-php كل ما لا تغطيه.','No skill claims this. %d matching abilities are available — use them directly, and nibwp/execute-php for anything they do not cover.'=>'لا توجد مهارة تتولى هذا الأمر. تتوفر %d من القدرات المطابقة — استخدمها مباشرةً، واستخدم nibwp/execute-php لكل ما لا تغطيه.','No skill, workflow or ability owns this — which makes nibwp/execute-php the right tool, not a last resort. Go ahead and build it in PHP. (Its last-resort warning applies only to writing builder content a skill owns; that is not this.)'=>'لا توجد مهارة أو سير عمل أو قدرة تتولى هذا الأمر — ما يجعل nibwp/execute-php الأداة الصحيحة، لا الملاذ الأخير. تابع وابنِه بلغة PHP. (تحذير الملاذ الأخير الخاص بها ينطبق فقط على كتابة محتوى أداة بناء تتولاه مهارة؛ وهذه ليست تلك الحالة.)','List Directory'=>'عرض محتويات المجلد','Load integration playbook on demand'=>'تحميل دليل تشغيل التكامل عند الطلب','Integration — Record feedback'=>'التكامل — تسجيل ملاحظات','Load skill playbook on demand'=>'تحميل دليل تشغيل المهارة عند الطلب','Memory Store'=>'تخزين في الذاكرة','Memory Recall'=>'استرجاع من الذاكرة','Memory Delete'=>'حذف من الذاكرة','Memory List Keys'=>'عرض مفاتيح الذاكرة','Multi-Execute (batch abilities)'=>'تنفيذ متعدد (قدرات مجمّعة)','Preferences — Get'=>'التفضيلات — جلب','Preferences — Set'=>'التفضيلات — تعيين','Read Audit Log'=>'قراءة سجل التدقيق','Read File'=>'قراءة ملف','Skill Preflight'=>'فحص ما قبل تشغيل المهارة','Templates — List'=>'القوالب — عرض','Templates — Apply'=>'القوالب — تطبيق','WooCommerce – List Products'=>'WooCommerce – عرض المنتجات','WooCommerce – Get Product'=>'WooCommerce – جلب منتج','WooCommerce – Create Product'=>'WooCommerce – إنشاء منتج','WooCommerce – Update Product'=>'WooCommerce – تحديث منتج','WooCommerce – Delete Product'=>'WooCommerce – حذف منتج','WooCommerce – List Orders'=>'WooCommerce – عرض الطلبات','WooCommerce – Get Order'=>'WooCommerce – جلب طلب','WooCommerce – Update Order Status'=>'WooCommerce – تحديث حالة الطلب','WooCommerce – List Customers'=>'WooCommerce – عرض العملاء','WooCommerce – List Coupons'=>'WooCommerce – عرض القسائم','WooCommerce – Create Coupon'=>'WooCommerce – إنشاء قسيمة','WooCommerce – Get Reports'=>'WooCommerce – جلب التقارير','Post not found.'=>'المقالة غير موجودة.','Title is required.'=>'العنوان مطلوب.','Failed to delete post.'=>'فشل حذف المقالة.','URL is required.'=>'الرابط (URL) مطلوب.','Attachment not found.'=>'المرفق غير موجود.','That attachment has no file on disk.'=>'لا يوجد ملف على القرص لهذا المرفق.','That source file cannot be read.'=>'تتعذّر قراءة الملف المصدر.','Provide either url or path.'=>'حدّد إما url أو path.','That file type is not allowed in the media library.'=>'نوع الملف هذا غير مسموح به في مكتبة الوسائط.','Could not write the replacement file.'=>'تعذّرت كتابة الملف البديل.','Failed to delete attachment.'=>'فشل حذف المرفق.','Taxonomy is required.'=>'التصنيف مطلوب.','Taxonomy does not exist.'=>'التصنيف غير موجود.','Taxonomy and name are required.'=>'التصنيف والاسم مطلوبان.','Term not found.'=>'المصطلح غير موجود.','Failed to delete term.'=>'فشل حذف المصطلح.','post_id and content are required.'=>'الحقلان post_id وcontent مطلوبان.','Failed to create comment.'=>'فشل إنشاء التعليق.','Comment not found.'=>'التعليق غير موجود.','Failed to delete comment.'=>'فشل حذف التعليق.','Menu not found.'=>'القائمة غير موجودة.','Failed to get menu items.'=>'فشل جلب عناصر القائمة.','Menu name is required.'=>'اسم القائمة مطلوب.','Referenced post not found.'=>'المقالة المشار إليها غير موجودة.','Referenced term not found.'=>'المصطلح المشار إليه غير موجود.','User not found.'=>'المستخدم غير موجود.','Option name is required.'=>'اسم الخيار مطلوب.','Option does not exist.'=>'الخيار غير موجود.','Option not found.'=>'لم يُعثر على الخيار.','Search query is required.'=>'عبارة البحث مطلوبة.','object_type must